#!/usr/bin/python
# -*- coding: utf-8 -*-

# Copyright: (c) 2012, Michael DeHaan <michael.dehaan@gmail.com>, and others
# GNU General Public License v3.0+ (see COPYING or https://www.gnu.org/licenses/gpl-3.0.txt)

from __future__ import absolute_import, division, print_function
__metaclass__ = type


import errno
import json
import shlex
import shutil
import os
import subprocess
import sys
import traceback
import signal
import time
import syslog
import multiprocessing

from ansible.module_utils._text import to_text, to_bytes

PY3 = sys.version_info[0] == 3

syslog.openlog('ansible-%s' % os.path.basename(__file__))
syslog.syslog(syslog.LOG_NOTICE, 'Invoked with %s' % " ".join(sys.argv[1:]))

# pipe for communication between forked process and parent
ipc_watcher, ipc_notifier = multiprocessing.Pipe()
job_path = None


def notice(msg):
    syslog.syslog(syslog.LOG_NOTICE, msg)


def end(res, exit_msg):
    if res is not None:
        print(json.dumps(res))
        sys.stdout.flush()
    sys.exit(exit_msg)


def jwrite(info):
    tmp_job_path = job_path + '.tmp'
    try:
        data = json.dumps(info)
        with open(tmp_job_path, 'w') as jobfile:
            jobfile.write(data)
        os.rename(tmp_job_path, job_path)
    except Exception as e:
        notice('Could not write async result to %s: %s' % (job_path, to_text(e)))
        raise


def _error_result(jid, msg, started=0, **kwargs):
    result = dict(failed=True, msg=msg, ansible_job_id=jid, started=started, finished=1)
    if job_path is not None:
        result['results_file'] = job_path
    result.update(kwargs)
    return result


def _record_error(result):
    try:
        jwrite(result)
    except Exception as e:
        result['msg'] += '; could not write async result: %s' % to_text(e)
    return result


def _cleanup(wrapped_module, preserve_tmp):
    if not preserve_tmp:
        shutil.rmtree(os.path.dirname(wrapped_module), True)


def daemonize_self():
    # daemonizing code: http://aspn.activestate.com/ASPN/Cookbook/Python/Recipe/66012
    try:
        pid = os.fork()
        if pid > 0:
            # exit first parent
            end(None, 0)
    except OSError as e:
        raise OSError(e.errno, 'fork #1 failed: %s' % e.strerror)

    # decouple from parent environment (does not chdir / to keep the directory context the same as for non async tasks)
    os.setsid()
    os.umask(int('022', 8))

    # do second fork
    try:
        pid = os.fork()
        if pid > 0:
            end(None, 0)
    except OSError as e:
        raise OSError(e.errno, 'fork #2 failed: %s' % e.strerror)

    dev_null = open('/dev/null', 'w')
    os.dup2(dev_null.fileno(), sys.stdin.fileno())
    os.dup2(dev_null.fileno(), sys.stdout.fileno())
    os.dup2(dev_null.fileno(), sys.stderr.fileno())


# NB: this function copied from module_utils/json_utils.py. Ensure any changes are propagated there.
# FUTURE: AnsibleModule-ify this module so it's Ansiballz-compatible and can use the module_utils copy of this function.
def _filter_non_json_lines(data):
    '''
    Used to filter unrelated output around module JSON output, like messages from
    tcagetattr, or where dropbear spews MOTD on every single command (which is nuts).

    Filters leading lines before first line-starting occurrence of '{', and filter all
    trailing lines after matching close character (working from the bottom of output).
    '''
    warnings = []

    # Filter initial junk
    lines = data.splitlines()

    for start, line in enumerate(lines):
        line = line.strip()
        if line.startswith(u'{'):
            break
    else:
        raise ValueError('No start of json char found')

    # Filter trailing junk
    lines = lines[start:]

    for reverse_end_offset, line in enumerate(reversed(lines)):
        if line.strip().endswith(u'}'):
            break
    else:
        raise ValueError('No end of json char found')

    if reverse_end_offset > 0:
        # Trailing junk is uncommon and can point to things the user might
        # want to change.  So print a warning if we find any
        trailing_junk = lines[len(lines) - reverse_end_offset:]
        warnings.append('Module invocation had junk after the JSON data: %s' % '\n'.join(trailing_junk))

    lines = lines[:(len(lines) - reverse_end_offset)]

    return ('\n'.join(lines), warnings)


def _get_interpreter(module_path):
    with open(module_path, 'rb') as module_fd:
        head = module_fd.read(1024)
        if head[0:2] != b'#!':
            return None
        return head[2:head.index(b'\n')].strip().split(b' ')


def _make_temp_dir(path):
    # TODO: Add checks for permissions on path.
    try:
        os.makedirs(path)
    except OSError as e:
        if e.errno != errno.EEXIST:
            raise


def _run_module(wrapped_cmd, jid, path):
    global job_path
    job_path = path

    # signal grandchild process started and isolated from being terminated
    # by the connection being closed sending a signal to the job group
    ipc_notifier.send(True)
    ipc_notifier.close()

    outdata = ''
    stderr = ''
    try:
        cmd = [to_bytes(c, errors='surrogate_or_strict') for c in shlex.split(wrapped_cmd)]
        # call the module interpreter directly (for non-binary modules)
        # this permits use of a script for an interpreter on non-Linux platforms
        interpreter = _get_interpreter(cmd[0])
        if interpreter:
            cmd = interpreter + cmd
        script = subprocess.Popen(cmd, shell=False, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                  stderr=subprocess.PIPE)

        (outdata, stderr) = script.communicate()
        if PY3:
            outdata = outdata.decode('utf-8', 'surrogateescape')
            stderr = stderr.decode('utf-8', 'surrogateescape')

        (filtered_outdata, json_warnings) = _filter_non_json_lines(outdata)

        result = json.loads(filtered_outdata)

        if json_warnings:
            # merge JSON junk warnings with any existing module warnings
            module_warnings = result.get('warnings', [])
            if not isinstance(module_warnings, list):
                module_warnings = [module_warnings]
            module_warnings.extend(json_warnings)
            result['warnings'] = module_warnings

        if stderr:
            result['stderr'] = stderr
        result['ansible_job_id'] = jid
        result['started'] = 1
        result['finished'] = 1
        result['results_file'] = job_path
        result.setdefault('failed', False)

    except (OSError, IOError) as e:
        result = _error_result(jid, to_text(e), started=1, cmd=wrapped_cmd,
                               outdata=outdata, stderr=stderr)

    except Exception:
        result = _error_result(jid, traceback.format_exc(), started=1, cmd=wrapped_cmd,
                               data=outdata, stderr=stderr)

    jwrite(result)


def _stop_process_group(pid):
    try:
        os.killpg(pid, signal.SIGKILL)
    except OSError as e:
        if e.errno != errno.ESRCH:
            raise
    try:
        os.waitpid(pid, 0)
    except OSError as e:
        if e.errno != errno.ECHILD:
            raise


def _watch_module(pid, time_limit, jid):
    try:
        os.setpgid(pid, pid)
    except OSError as e:
        # The worker can finish before the watcher sets its process group.
        if e.errno != errno.ESRCH:
            raise

    deadline = time.time() + time_limit
    while True:
        child_pid, status = os.waitpid(pid, os.WNOHANG)
        if child_pid:
            return
        remaining = deadline - time.time()
        if remaining <= 0:
            notice('Now killing %s' % pid)
            _stop_process_group(pid)
            jwrite(_error_result(jid, 'async task timed out after %s seconds' % time_limit,
                                 started=1, child_pid=pid, timed_out=True))
            return
        time.sleep(min(5, remaining))


def _immediate_end(result, preserve_tmp, exit_code):
    response = result.copy()
    response['_ansible_suppress_tmpdir_delete'] = not preserve_tmp
    end(response, exit_code)


def main():
    global job_path
    job_path = None
    if len(sys.argv) < 5:
        jid = '%s.%d' % (sys.argv[1], os.getpid()) if len(sys.argv) > 1 else None
        end(_error_result(jid, 'usage: async_wrapper <jid> <time_limit> <modulescript> '
                               '<argsfile> [-preserve_tmp]. Humans, do not call directly!'), 1)

    jid = "%s.%d" % (sys.argv[1], os.getpid())
    wrapped_module = sys.argv[3]
    argsfile = sys.argv[4]
    if '-tmp-' not in os.path.dirname(wrapped_module):
        preserve_tmp = True
    elif len(sys.argv) > 5:
        preserve_tmp = sys.argv[5] == '-preserve_tmp'
    else:
        preserve_tmp = False
    # consider underscore as no argsfile so we can support passing of additional positional parameters
    if argsfile != '_':
        cmd = "%s %s" % (wrapped_module, argsfile)
    else:
        cmd = wrapped_module
    async_dir = os.environ.get('ANSIBLE_ASYNC_DIR', '~/.ansible_async')

    # setup job output directory
    jobdir = os.path.expanduser(async_dir)
    job_path = os.path.join(jobdir, jid)

    try:
        _make_temp_dir(jobdir)
    except Exception as e:
        result = _error_result(jid, 'could not create async directory %s: %s' % (jobdir, to_text(e)),
                               exception=traceback.format_exc())
        _cleanup(wrapped_module, preserve_tmp)
        _immediate_end(result, preserve_tmp, 1)

    try:
        time_limit = int(sys.argv[2])
        if time_limit < 0:
            raise ValueError('time limit must be non-negative')
    except ValueError as e:
        result = _record_error(_error_result(jid, 'invalid time limit: %s' % to_text(e)))
        _cleanup(wrapped_module, preserve_tmp)
        _immediate_end(result, preserve_tmp, 1)

    try:
        jwrite(dict(started=1, finished=0, failed=False, ansible_job_id=jid,
                    results_file=job_path))
    except Exception as e:
        result = _error_result(jid, 'could not write async job file %s: %s' % (job_path, to_text(e)))
        _cleanup(wrapped_module, preserve_tmp)
        _immediate_end(result, preserve_tmp, 1)

    # immediately exit this process, leaving an orphaned process
    # running which immediately forks a supervisory timing process

    try:
        pid = os.fork()
    except Exception as e:
        result = _record_error(_error_result(jid, 'fork failed: %s' % to_text(e)))
        _cleanup(wrapped_module, preserve_tmp)
        _immediate_end(result, preserve_tmp, 1)

    if pid:
        # Give the worker time to open the module before its temporary files are removed.
        ipc_notifier.close()
        try:
            if ipc_watcher.poll(2.5):
                notification = ipc_watcher.recv()
                if isinstance(notification, dict):
                    _immediate_end(notification, preserve_tmp, 1)
        except EOFError:
            result = _record_error(_error_result(jid, 'async worker exited before startup'))
            _immediate_end(result, preserve_tmp, 1)
        except Exception as e:
            result = _error_result(jid, 'could not confirm async startup: %s' % to_text(e))
            _immediate_end(result, preserve_tmp, 1)

        notice('Return async_wrapper task started.')
        _immediate_end(dict(started=1, finished=0, failed=False, ansible_job_id=jid,
                            results_file=job_path), preserve_tmp, 0)

    # The child handles every later error through the job file and the IPC pipe.
    ipc_watcher.close()
    try:
        daemonize_self()
        notice('Starting module and watcher')
        sub_pid = os.fork()
    except Exception as e:
        result = _record_error(_error_result(jid, 'could not start async worker: %s' % to_text(e)))
        try:
            ipc_notifier.send(result)
        except Exception:
            pass
        ipc_notifier.close()
        _cleanup(wrapped_module, preserve_tmp)
        end(None, 1)

    if sub_pid:
        ipc_notifier.close()
        try:
            _watch_module(sub_pid, time_limit, jid)
        except Exception as e:
            notice('error watching async worker: %s' % to_text(e))
            _stop_process_group(sub_pid)
            _record_error(_error_result(jid, 'error watching async worker: %s' % to_text(e),
                                        started=1, child_pid=sub_pid))
            end(None, 1)
        finally:
            _cleanup(wrapped_module, preserve_tmp)
        end(None, 0)

    try:
        notice('Start module (%s)' % os.getpid())
        _run_module(cmd, jid, job_path)
        notice('Module complete (%s)' % os.getpid())
    except Exception as e:
        notice('error running async module: %s' % to_text(e))
        _record_error(_error_result(jid, 'error running async module: %s' % to_text(e),
                                    started=1, child_pid=os.getpid(), exception=traceback.format_exc()))
        end(None, 1)
    end(None, 0)


if __name__ == '__main__':
    main()

